# Tests for SecurityExceptionRegistry
# -----------------------------------------------------------------------------
class TestSecurityExceptionRegistry:
    def test_singleton(self):
        """Registry should be a singleton."""
        r1 = SecurityExceptionRegistry()
        r2 = SecurityExceptionRegistry()
        assert r1 is r2

    def test_register_adds_exception(self, reset_registry):
        registry = reset_registry
        exc = SecurityError("test", error_code="SEC-001")
        registry.register(exc)
        all_exceptions = registry.get_all()
        assert len(all_exceptions) == 1
        assert all_exceptions[0]["message"] == "test"
        assert all_exceptions[0]["error_code"] == "SEC-001"

    def test_get_all_respects_limit(self, reset_registry):
        registry = reset_registry
        for i in range(5):
            exc = SecurityError(f"err{i}", error_code=f"SEC-00{i}")
            registry.register(exc)
        result = registry.get_all(limit=3)
        assert len(result) == 3
        # Should return the last 3
        assert result[0]["message"] == "err2"
        assert result[1]["message"] == "err3"
        assert result[2]["message"] == "err4"

    def test_get_by_code_filters_correctly(self, reset_registry):
        registry = reset_registry
        exc1 = SecurityError("err1", error_code="CODE-A")
        exc2 = SecurityError("err2", error_code="CODE-B")
        exc3 = SecurityError("err3", error_code="CODE-A")
        registry.register(exc1)
        registry.register(exc2)
        registry.register(exc3)
        found = registry.get_by_code("CODE-A")
        assert len(found) == 2
        assert found[0]["message"] == "err1"
        assert found[1]["message"] == "err3"

    def test_get_by_user_filters_by_context_user_id(self, reset_registry):
        registry = reset_registry
        exc1 = AuthenticationError("bad", user_id="user1")
        exc2 = AuthenticationError("bad", user_id="user2")
        exc3 = SecurityError("generic", context={"user_id": "user1"})
        registry.register(exc1)
        registry.register(exc2)
        registry.register(exc3)
        found = registry.get_by_user("user1")
        assert len(found) == 2
        messages = {e["message"] for e in found}
        assert "bad" in messages
        assert "generic" in messages

    def test_clear_removes_all_exceptions(self, reset_registry):
        registry = reset_registry
        exc = SecurityError("test")
        registry.register(exc)
        assert len(registry.get_all()) == 1
        registry.clear()
        assert len(registry.get_all()) == 0

    def test_get_summary_returns_counts(self, reset_registry):
        registry = reset_registry
        exc1 = SecurityError("e1", error_code="A")
        exc2 = SecurityError("e2", error_code="B")
        exc3 = SecurityError("e3", error_code="A")
        registry.register(exc1)
        registry.register(exc2)
        registry.register(exc3)
        summary = registry.get_summary()
        assert summary["total"] == 3
        assert summary["by_error_code"] == {"A": 2, "B": 1}
        assert summary["last_exception"]["message"] == "e3"
        assert summary["version"] == registry.version()

    def test_validate_checks_max_size(self, reset_registry):
        registry = reset_registry
        # default max_size is 10000, so valid
        result = registry.validate()
        assert result["is_valid"] is True
        assert result["errors"] == []
        # modify to invalid
        registry._max_size = 0
        result = registry.validate()
        assert result["is_valid"] is False
        assert "max_size must be positive" in result["errors"]

    def test_to_dict_returns_registry_state(self, reset_registry):
        registry = reset_registry
        exc = SecurityError("test")
        registry.register(exc)
        data = registry.to_dict()
        assert data["exception_count"] == 1
        assert data["max_size"] == 10000
        assert data["version"] == registry.version()

    def test_from_dict_creates_registry_with_given_state(self):
        data = {"max_size": 5000, "version": 3}
        new_registry = SecurityExceptionRegistry.from_dict(data)
        assert new_registry._max_size == 5000
        assert new_registry._version == 3
        # Should not copy exceptions from the singleton; they remain empty
        assert len(new_registry.get_all()) == 0

    def test_clone_copies_exceptions_and_increments_version(self, reset_registry):
        registry = reset_registry
        exc = SecurityError("test")
        registry.register(exc)
        cloned = registry.clone()
        assert cloned is not registry
        assert cloned._version == registry._version + 1
        assert len(cloned.get_all()) == 1
        assert cloned.get_all()[0]["message"] == "test"

    def test_snapshot_returns_summary_snapshot(self, reset_registry):
        registry = reset_registry
        exc = SecurityError("test")
        registry.register(exc)
        snap = registry.snapshot()
        assert snap["version"] == registry.version()
        assert snap["exception_count"] == 1
        assert "timestamp" in snap

    def test_version_returns_current_version(self, reset_registry):
        registry = reset_registry
        assert registry.version() == 1
        registry._version = 5
        assert registry.version() == 5

    def test_audit_trail_records_register_and_touch_actions(self, reset_registry):
        registry = reset_registry
        exc = SecurityError("test")
        registry.register(exc)
        registry.touch("admin")
        trail = registry.audit_trail()
        assert len(trail) == 2
        assert trail[0]["action"] == "REGISTER"
        assert trail[0]["performed_by"] == "system"
        assert trail[1]["action"] == "TOUCH"
        assert trail[1]["performed_by"] == "admin"

    def test_reset_clears_all_and_resets_version_and_audit(self, reset_registry):
        registry = reset_registry
        exc = SecurityError("test")
        registry.register(exc)
        registry.touch("tester")
        registry._version = 10
        registry.reset()
        assert len(registry.get_all()) == 0
        assert registry.version() == 1
        assert len(registry.audit_trail()) == 0
        assert len(registry._snapshots) == 0  # snapshots are also cleared


